  const range=colorUpper()-threshold;
  const stops=[[threshold,'#f16b2f'],[threshold+range*150/1950,'#ffb931'],[threshold+range*350/1950,'#f6ed45'],[threshold+range*700/1950,'#91d94c'],[threshold+range*1050/1950,'#38c9b2'],[threshold+range*1450/1950,'#31a8e1'],[threshold+range,'#396bd0']];
