function remapImportedValhallaRoutes(routes){
  let changed=false;
  for(const route of routes){
    if(!route.live_valhalla)continue;
    const before=JSON.stringify([route.authority_source??null,route.authority_ranges??null,route.cells.map(c=>[c.cell_id,c.outside_here_distance_m])]);
    if(route.authority_source!=='valhalla_maneuvers_v1'){
      route.cells=[];route.authority_ranges=[];route.authority_offsets=null;route.authority_only_cell_count=null;
      route.authority_rule='Original Valhalla highway maneuvers are unavailable; AVM evaluation is paused.';
      route.avm_status='highway_evidence_unavailable';
    }else{
      const prior=new Map(route.cells.map(cell=>[cell.cell_id,cell]));
      const mapped=window.SurviveAvm.mapRoute(route);
      for(const cell of mapped.cells){const old=prior.get(cell.cell_id);if(old&&old.latitude===cell.latitude&&old.longitude===cell.longitude&&Number.isFinite(old.estimate_ppsqft)&&old.estimate_ppsqft>0){for(const field of ['estimate_ppsqft','value_origin','acquired_at','source_artifact','source_hash','cache_source_kind','cached_at'])if(old[field]!==undefined)cell[field]=old[field];}}
      Object.assign(route,mapped);
    }
    if(before!==JSON.stringify([route.authority_source??null,route.authority_ranges??null,route.cells.map(c=>[c.cell_id,c.outside_here_distance_m])]))changed=true;
  }
  routes.highwayEvidenceChanged=changed;
  return routes;
}
