async function runParallelAutomaticRound(plan,round,active,sampled){
  const screen=state.poolScreening,start=plan.attempt_records.length,items=sampled.selected_cells.map((selected,offset)=>{const cell=plan.candidate_pool_snapshot.cells.find(x=>x.cell_id===selected.cell_id),routeId=(selected.selected_for_route_ids??[]).find(id=>active.includes(id))??selected.initiated_by;if(!cell||!routeId||!cell.route_ids.includes(routeId))throw Error('Selected cell is outside the frozen authorization.');return{cell,routeId,attemptIndex:start+offset};});
  const reserve=await providerFetch('/api/providers/avm/round',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan_id:plan.plan_id,round_index:round,selections:items.map(({cell,routeId,attemptIndex})=>({attempt_index:attemptIndex,route_id:routeId,cell:{cell_id:cell.cell_id,latitude:cell.latitude,longitude:cell.longitude}}))})}),grant=await appJson(reserve,'Automatic round reservation',true);
  if(!reserve.ok||grant.plan_id!==plan.plan_id||grant.round_index!==round||grant.reserved_count!==items.length||grant.parallel_rounds!==true||grant.provider_attempted!==false)throw Error(grant.error||'The server did not reserve the exact round. No AVM request was sent by this browser.');
  appendPoolLedgerEvent(plan,{event:'automatic_round_reserved',round_index:round,status:'exact_cells_reserved',message:items.length+' exact cells reserved for bounded parallel calls; no retries.'});
  let used=0,completed=0,failed=0,uncertain=false,stopped=false,stopReason=null,launched=0;
  for(let offset=0;offset<items.length;offset+=6){
    if(screen.automatic_evolution_stop_requested||!$('automatic-route-pruning').checked){stopped=true;stopReason='automation turned off before the next group of requests';break;}
    const group=items.slice(offset,offset+6),started=Date.now();let mapNeedsRedraw=false,mapZonesNeedRedraw=false;launched+=group.length;
    const responses=await Promise.all(group.map(async item=>{try{const response=await providerFetch('/api/providers/avm/attempt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan_id:plan.plan_id,attempt_index:item.attemptIndex,round_index:round,route_id:item.routeId,cell:{cell_id:item.cell.cell_id,latitude:item.cell.latitude,longitude:item.cell.longitude}})});return{response,result:await appJson(response,'Preauthorized route-evolution AVM attempt',true)};}catch(error){return{error};}}));
    for(let i=0;i<group.length;i++){
      const {cell,routeId,attemptIndex}=group[i],{response,result,error}=responses[i],base={cell_id:cell.cell_id,route_id:routeId,round_index:round,attempt_index:attemptIndex};
      if(result?.provider_attempted===true){used++;state.providerCalls.RentCast++;}if(error||result?.uncertain===true||typeof result?.provider_attempted!=='boolean'){uncertain=true;stopReason=error?.message||result?.error||'An AVM outcome is unknown; no replay';plan.attempt_records.push({...base,status:'outcome_unknown',provider_attempted:result?.provider_attempted??null});}
      else if(response.ok&&Number.isFinite(result.estimate_ppsqft)&&result.estimate_ppsqft>0){mapZonesNeedRedraw=applyPoolEstimate({cell_id:cell.cell_id,latitude:cell.latitude,longitude:cell.longitude,members:cell.route_ids.map(route_id=>({route_id}))},result,plan)||mapZonesNeedRedraw;plan.attempt_records.push({...base,status:result.provider_attempted?'complete':'cache_hit',provider_attempted:result.provider_attempted,estimate_ppsqft:result.estimate_ppsqft,source_kind:result.source_kind??null,acquired_at:result.acquired_at??null});completed++;mapNeedsRedraw=true;}
      else if(result.provider_attempted===true){failed++;plan.attempt_records.push({...base,status:'failed',provider_attempted:true,error:String(result.error??'Confirmed provider failure').slice(0,250)});}
      else{stopped=true;stopReason=String(result.error??'Server stopped before attempt').slice(0,250);plan.attempt_records.push({...base,status:'not_attempted_stop',provider_attempted:false});}
      appendPoolLedgerEvent(plan,{event:'automatic_result',selection_index:attemptIndex+1,cell_id:cell.cell_id,status:plan.attempt_records.at(-1).status,provider_attempted:result?.provider_attempted??null});screen.provider_attempts=(screen.provider_attempts??0)+Number(result?.provider_attempted===true);screen.results=rankPoolResults(state.routes,plan,plan.attempt_records);notePoolRankingUpdated();renderCandidates();renderPoolScreening();renderAutomaticEvolution();providerCounts();
    }
    if(mapNeedsRedraw)refreshSelectedRouteEvidence(mapZonesNeedRedraw);
    if(uncertain||stopped)break;
    if(offset+6<items.length){const delay=400-(Date.now()-started);if(delay>0)await new Promise(resolve=>setTimeout(resolve,delay));}
  }
  for(const {cell,routeId,attemptIndex}of items.slice(launched))plan.attempt_records.push({cell_id:cell.cell_id,route_id:routeId,round_index:round,attempt_index:attemptIndex,status:'not_attempted_stop',provider_attempted:false});
  return{used,completed,failed,uncertain,stopped,stopReason};
}
