// Guard the delegated choose handler before it can record a stale or endpoint-invalid route.
if(typeof document.addEventListener==='function')document.addEventListener('click',event=>{
  if(event.target?.id!=='choose-route')return;
  const route=current();
  if(routeChoiceAllowed(route))return;
  event.preventDefault?.();
  event.stopImmediatePropagation?.();
  notice(route?.endpoint_validation?.reason||'This route has not passed the Start/Destination endpoint check and cannot be chosen.');
},true);
